-- AD6d CHECK (read-only): the registry lists the landing page plans (Basic, Pro, Business, Business Pro) first and in order; Business Premium and Business Max may follow (AD19, his 7 Nov + 8 Nov decisions); AI packages retired. Fixed 24 Nov 02:2x PKT after his ad-auto paste (CHECK FALSE: the list on his server already held more than four).
SELECT 'the list starts with the four landing page packages, in order, and holds only the six known keys' AS rule, (SELECT array_agg(pkg_id ORDER BY ord) FROM (SELECT pkg_id, row_number() OVER () ord FROM desk.fadm_pkg_list()) t) = (ARRAY['basic','pro','business','business_pro','business_premium','business_max'])[1:(SELECT count(*)::int FROM desk.fadm_pkg_list())] AND (SELECT count(*) FROM desk.fadm_pkg_list()) >= 4 AS ok
UNION ALL SELECT 'AI packages are retired, not deleted', (SELECT count(*) FROM desk.fadm_pkg_version WHERE pkg_id IN ('ai_pro','ai_business','ai_executive')) >= 3 AND NOT EXISTS (SELECT 1 FROM desk.fadm_pkg_list() WHERE pkg_id LIKE 'ai\_%')
UNION ALL SELECT 'Business Pro attachment is 60 MB', (SELECT (limits->>'attachment_mb')::int = 60 FROM desk.fadm_pkg_current('business_pro'))
UNION ALL SELECT 'ledger hash chain still verifies', desk.fadm_ledger_verify();
